from rdkit import Chem

smiles = "[B-](OC1=PC(C(=O)O[Sn]2N(c3c(C(C)C)cccc3C(C)C)C(C)=CC(C)N2c4c(C(C)C)cccc4C(C)C)C1C(=O)OC)(c5c(F)c(F)c(F)c(F)c5F)(c6c(F)c(F)c(F)c(F)c6F)c7c(F)c(F)c(F)c(F)c7F"
mol = Chem.MolFromSmiles(smiles)
if mol is None:
    print("PARSE FAILED")
else:
    mol = Chem.AddHs(mol)
    print("atoms:", mol.GetNumAtoms())
    from collections import Counter
    print(Counter(a.GetSymbol() for a in mol.GetAtoms()))
    # find the Sn atom and its neighbors
    for a in mol.GetAtoms():
        if a.GetSymbol()=='Sn':
            print("Sn idx", a.GetIdx(), "neighbors:", [(n.GetSymbol(), n.GetIdx()) for n in a.GetNeighbors()])
    for a in mol.GetAtoms():
        if a.GetSymbol()=='P':
            print("P idx", a.GetIdx(), "neighbors:", [(n.GetSymbol(), n.GetIdx(), str(mol.GetBondBetweenAtoms(a.GetIdx(),n.GetIdx()).GetBondType())) for n in a.GetNeighbors()])
